\begin{ex}%[6H4C1]
\immini[thm]{
Đếm số hình vuông trong hình sau
}{
\begin{tikzpicture}
    % Vẽ lưới
    \draw[step=1cm] (0, 0) grid (4, 4);

    % Vẽ hình vuông bên ngoài
    \draw[thick] (0, 0) rectangle (4, 4);

    % Vẽ các hình tròn đặc tại các điểm lưới
    \fill (0, 0) circle (2pt);
    \fill (0, 1) circle (2pt);
    \fill (0, 2) circle (2pt);
    \fill (0, 3) circle (2pt);
    \fill (0, 4) circle (2pt);

    \fill (1, 0) circle (2pt);
    \fill (1, 1) circle (2pt);
    \fill (1, 2) circle (2pt);
    \fill (1, 3) circle (2pt);
    \fill (1, 4) circle (2pt);

    \fill (2, 0) circle (2pt);
    \fill (2, 1) circle (2pt);
    \fill (2, 2) circle (2pt);
    \fill (2, 3) circle (2pt);
    \fill (2, 4) circle (2pt);

    \fill (3, 0) circle (2pt);
    \fill (3, 1) circle (2pt);
    \fill (3, 2) circle (2pt);
    \fill (3, 3) circle (2pt);
    \fill (3, 4) circle (2pt);

    \fill (4, 0) circle (2pt);
    \fill (4, 1) circle (2pt);
    \fill (4, 2) circle (2pt);
    \fill (4, 3) circle (2pt);
    \fill (4, 4) circle (2pt);

    % Vẽ các hình tròn rỗng tại các góc dưới cùng
    \draw[thick] (0, 0) circle (2pt);
    \draw[thick] (4, 0) circle (2pt);

\end{tikzpicture}
}
\loigiai{
Số hình vuông có cạnh bằng 1 là $16$\\
Số hình vuông có cạnh là 2 bằng $9$\\
Số hình vuông có cạnh là 3 bằng $4$\\
Số hình vuông có cạnh là 4 bằng $1$\\
Có 30 hình vuông trong hình
}\end{ex}
